import{_ as o,o as r,c as t,a2 as _}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Keynote: The Road to Open Source Ceph: Bloomberg’s Enterprise Ceph Journey","description":"","frontmatter":{"title":"Keynote: The Road to Open Source Ceph: Bloomberg’s Enterprise Ceph Journey","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","开源","企业应用","Bloomberg"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Keynote_-_The_Road_to_Open_Source_Ceph_-_Bloomberg_s_Enterprise_Ceph_Journey.md","filePath":"posts/2023/Keynote_-_The_Road_to_Open_Source_Ceph_-_Bloomberg_s_Enterprise_Ceph_Journey.md","lastUpdated":1780459816000}'),p={name:"posts/2023/Keynote_-_The_Road_to_Open_Source_Ceph_-_Bloomberg_s_Enterprise_Ceph_Journey.md"};function n(l,e,s,i,g,a){return r(),t("div",null,[...e[0]||(e[0]=[_("<p>Bloomberg存储工程负责人Matthew Leonard在Cephalocon会议上发表了题为《开源Ceph之路：Bloomberg的企业Ceph之旅》的演讲。以下是会议内容的总结：</p><ol><li><p><strong>Bloomberg的开放源代码之旅</strong>：Bloomberg从2000年开始转向开放源代码，建立了开源项目办公室，赞助了多个技术和基金会，包括Ceph和云原生计算基金会，并在Kubernetes生态系统中扮演重要角色。</p></li><li><p><strong>基础设施转型</strong>：2016年，Bloomberg决定转向云原生基础设施，采用Kubernetes、虚拟化和S3等平台，支持数以万计的虚拟机和数十亿次的S3请求。</p></li><li><p><strong>Ceph在Bloomberg的应用</strong>：Bloomberg使用Ceph支持其S3服务，运行着多个集群，管理着数百PB的存储，并利用Ceph的多站点部署等功能。</p></li><li><p><strong>开源贡献与项目</strong>：Bloomberg开发了多个开源项目，如Memory Profiler，并设立了Bloomberg自由和开源软件基金，以支持开源社区的发展。</p></li><li><p><strong>未来计划与社区参与</strong>：Bloomberg计划开源其Telemetry收集系统和QoS堆栈，并希望更深入地参与Ceph社区，特别是在crimson、Ceph存储和RADOS网关等项目中。</p></li><li><p><strong>招聘信息</strong>：Bloomberg正在招聘，欢迎有兴趣的工程师与他们联系。</p></li><li><p><strong>结束语</strong>：Matthew Leonard感谢大家的参与，并鼓励大家在会议期间或通过公司展位与他们交流。</p></li></ol><p><strong>改进点</strong>：</p><ul><li>增加了Bloomberg的基础设施转型和开源贡献的详细描述。</li><li>突出了Bloomberg在Ceph应用中的具体实践和取得的成果。</li><li>明确了Bloomberg未来在Ceph社区中的参与计划和招聘信息。</li></ul>",4)])])}const C=o(p,[["render",n]]);export{m as __pageData,C as default};
